const app=document.querySelector('#admin-app'),toast=document.querySelector('#toast');
const labels={projects:'Проекты',services:'Компетенции',technologies:'Технологии',equipment:'Техника',vacancies:'Карьера',news:'Новости',documents:'Документы',partners:'Партнёрам',customers:'Заказчикам',procurement:'Закупки',stats:'Показатели'};
const names={latitude:'Широта (например 59.85)',longitude:'Долгота (например 30.30)',projectStatus:'Этап объекта',title:'Название',slug:'Адрес страницы (латиница)',excerpt:'Краткое описание',body:'Основной текст',region:'Регион',location:'Расположение',year:'Год',objectType:'Тип объекта',work:'Выполненные работы',specifications:'Характеристики',seoTitle:'SEO заголовок',seoDescription:'SEO описание',date:'Дата',city:'Город',employment:'Занятость',requirements:'Требования',conditions:'Условия',contact:'Контакт для отклика',category:'Категория',manufacturer:'Производитель',model:'Модель',value:'Значение',unit:'Единица',caption:'Подпись изображения',position:'Порядок',image:'Обложка',document:'Документ',video:'Видео'};
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let user,csrf,view='dashboard',dirty=false;
function notice(t){toast.textContent=t;setTimeout(()=>toast.textContent='',6000)}
async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:{...(body!==undefined?{'Content-Type':'application/json'}:{}),...(csrf?{'X-CSRF-Token':csrf}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.error||'Ошибка запроса');return data;}
function field(key,value='',type='text'){return `<label>${e(names[key]||key)}${type==='textarea'?`<textarea name="${e(key)}" rows="5">${e(value)}</textarea>`:`<input name="${e(key)}" type="${type}" value="${e(value)}" ${['title','slug'].includes(key)?'required':''}>`}</label>`}
function panel(title,html,actions=''){document.querySelector('#workspace').innerHTML=`<header><div><span class="eyebrow">ССТ / УПРАВЛЕНИЕ</span><h1>${e(title)}</h1></div>${actions}</header>${html}`;dirty=false;document.querySelectorAll('#workspace input,#workspace textarea,#workspace select').forEach(el=>el.addEventListener('input',()=>dirty=true));}
function shell(){app.innerHTML=`<aside><a class="admin-brand" href="/" target="_blank"><img src="/assets/emblem-white.svg" width="42" alt="ССТ"> ССТ<span>CONTENT STUDIO</span></a><nav>${Object.entries({dashboard:'Обзор',...labels,media:'Медиатека',...(user.role==='admin'?{leads:'Обращения',settings:'Настройки',users:'Команда',audit:'Журнал'}:{})}).map(([k,v])=>`<button data-view="${k}">${v}</button>`).join('')}</nav><footer>${e(user.name)}<small>${user.role==='admin'?'Администратор':'Редактор'}</small><button id="logout">Выйти</button></footer></aside><main id="workspace"></main>`;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(dirty&&!confirm('Уйти без сохранения изменений?'))return;go(b.dataset.view)});document.querySelector('#logout').onclick=async()=>{await api('logout','POST',{});location.reload()};go(view);}
async function go(next){view=next;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));try{if(labels[view])return await collection(view);if(view==='dashboard'){const d=await api('admin/dashboard');panel('Рабочий стол',`<p class="intro">Содержание, которое формирует образ компании.</p><div class="metrics">${Object.entries(d.counts).map(([k,n])=>`<div><strong>${n}</strong><span>${labels[k]}</span></div>`).join('')}${d.leads!==null?`<div><strong>${d.leads}</strong><span>Новых обращений</span></div>`:''}</div><section class="box"><h2>Последние материалы</h2>${d.recent.map(x=>`<p>${e(x.title)} <small>${e(x.status)}</small></p>`).join('')||'<p>Пока нет материалов. Создайте первый в нужном разделе.</p>'}<p>Пустые разделы автоматически скрыты на сайте.</p><p>Почтовые уведомления: ${d.mailConfigured?'настроены':'SMTP не настроен; обращения доступны в админке'}.</p>${d.notificationFailures?'<p>Есть недоставленные уведомления: '+d.notificationFailures+'</p>':''}</section>`);}else if(view==='media')await media();else if(view==='settings')await settings();else if(view==='leads')await leads();else if(view==='users')await users();else if(view==='audit'){const rows=await api('admin/audit');panel('Журнал действий',`<div class="box">${rows.map(x=>`<p><small>${e(new Date(x.created_at).toLocaleString('ru'))} · ${e(x.actor)}</small><br>${e(x.action)}</p>`).join('')||'Пока нет действий'}</div>`);}}catch(err){notice(err.message)}}
async function collection(kind){const rows=await api('admin/content/'+kind);panel(labels[kind],`<input id="search" type="search" placeholder="Поиск материалов"><div class="record-list">${rows.map(x=>`<button class="record" data-id="${x.id}"><span>${e(x.title)}<small>/${e(x.slug)}</small></span><span class="badge">${e({draft:'Черновик',published:'Опубликован',archived:'Архив'}[x.status])}</span></button>`).join('')||'<div class="empty">Добавьте первый материал. На сайте появятся только опубликованные записи.</div>'}</div>`,`<button id="new">＋ Добавить</button>`);document.querySelector('#new').onclick=()=>edit(kind,{});document.querySelectorAll('.record').forEach(b=>b.onclick=()=>edit(kind,rows.find(x=>x.id===b.dataset.id)));document.querySelector('#search').oninput=ev=>document.querySelectorAll('.record').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(ev.target.value.toLowerCase()));}
async function upload(file){const r=await fetch('/api/admin/media',{method:'POST',headers:{'X-CSRF-Token':csrf,'X-File-Name':encodeURIComponent(file.name)},body:file});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}
async function picker(callback){const rows=await api('admin/media'),dialog=document.createElement('dialog');dialog.className='media-dialog';dialog.innerHTML=`<header><h2>Выбрать файл</h2><button type="button" class="close">Закрыть</button></header><input type="search" placeholder="Поиск файла"><label class="upload">Загрузить новый файл<input type="file"></label><div class="media-grid">${rows.map(x=>`<button data-media="${x.id}" class="media-card">${x.mime.startsWith('image/')?`<img src="${e(x.url)}" alt="">`:'<span class="file-icon">↗</span>'}<span>${e(x.name)}</span></button>`).join('')}</div>`;document.body.append(dialog);dialog.showModal();const close=()=>{dialog.close();dialog.remove()};dialog.querySelector('.close').onclick=close;dialog.addEventListener('close',()=>dialog.remove());dialog.querySelectorAll('[data-media]').forEach(b=>b.onclick=()=>{callback(rows.find(x=>x.id===b.dataset.media).url);close()});dialog.querySelector('[type=search]').oninput=ev=>dialog.querySelectorAll('.media-card').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(ev.target.value.toLowerCase()));dialog.querySelector('[type=file]').onchange=async ev=>{try{const f=ev.target.files[0];if(!f)return;const d=await upload(f);callback(d.url);close();notice('Файл загружен')}catch(err){notice(err.message)}};}
function assetField(key,value){return `<div class="asset-field">${field(key,value)}<button type="button" data-pick="${key}">Медиатека</button></div>`}
function bindPick(form){form.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>picker(url=>{form.elements[b.dataset.pick].value=url;dirty=true}));}
async function edit(kind,item){let gallery=[...(item.gallery||[])];const extra={projects:['region','location','latitude','longitude','projectStatus','year','objectType','work'],services:[],technologies:['specifications'],equipment:['category','manufacturer','model','year','specifications'],vacancies:['city','employment','requirements','conditions','contact'],news:['date'],documents:[],partners:[],customers:[],procurement:['date','contact'],stats:['value','unit']}[kind];panel(item.id?'Редактирование материала':'Новый материал',`<form id="editor"><div class="editor-grid"><section class="box">${field('title',item.title)}${field('slug',item.slug)}${field('excerpt',item.excerpt,'textarea')}${field('body',item.body,'textarea')}${extra.map(k=>field(k,item[k],['work','specifications','requirements','conditions'].includes(k)?'textarea':'text')).join('')}</section><section class="box"><label>Статус<select name="status">${['draft','published','archived'].map(v=>`<option value="${v}" ${item.status===v?'selected':''}>${{draft:'Черновик',published:'Опубликован',archived:'Архив'}[v]}</option>`).join('')}</select></label>${field('position',item.position||0,'number')}<label class="check"><input name="featured" type="checkbox" ${item.featured?'checked':''}>Выделенный материал</label>${kind==='vacancies'?`<label class="check"><input name="closed" type="checkbox" ${item.closed?'checked':''}>Вакансия закрыта</label>`:''}${assetField('image',item.image)}${field('caption',item.caption)}${assetField('video',item.video)}${assetField('document',item.document)}${field('seoTitle',item.seoTitle)}${field('seoDescription',item.seoDescription,'textarea')}</section></div><section class="box"><h2>Галерея</h2><p>Перетаскивайте изображения или используйте стрелки.</p><div id="gallery" class="gallery-editor"></div><button id="add-image" type="button">＋ Добавить изображение</button></section><div class="save-bar"><button type="submit">Сохранить</button>${kind!=='stats'?'<button id="preview" type="button" class="secondary">Предпросмотр изменений</button>':''}<button id="back" type="button" class="secondary">К списку</button><span id="save-status" role="status"></span></div></form>`);const form=document.querySelector('#editor');bindPick(form);const data=()=>({...item,...Object.fromEntries(new FormData(form)),featured:form.elements.featured.checked,closed:form.elements.closed?.checked||false,gallery});const draw=()=>{const g=document.querySelector('#gallery');g.innerHTML=gallery.map((url,i)=>`<div draggable="true" data-index="${i}"><img src="${e(url)}" alt="Изображение ${i+1}"><div><button type="button" data-up="${i}" aria-label="Переместить влево">←</button><button type="button" data-down="${i}" aria-label="Переместить вправо">→</button><button type="button" data-remove="${i}" aria-label="Удалить изображение">×</button></div></div>`).join('');const move=(a,b)=>{if(b<0||b>=gallery.length)return;gallery.splice(b,0,gallery.splice(a,1)[0]);dirty=true;draw()};g.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>move(+b.dataset.up,+b.dataset.up-1));g.querySelectorAll('[data-down]').forEach(b=>b.onclick=()=>move(+b.dataset.down,+b.dataset.down+1));g.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{gallery.splice(+b.dataset.remove,1);dirty=true;draw()});g.querySelectorAll('[draggable]').forEach(el=>{el.ondragstart=ev=>ev.dataTransfer.setData('text/plain',el.dataset.index);el.ondragover=ev=>ev.preventDefault();el.ondrop=ev=>{ev.preventDefault();const a=Number(ev.dataTransfer.getData('text/plain'));if(Number.isInteger(a)&&a>=0&&a<gallery.length)move(a,+el.dataset.index)}})};draw();document.querySelector('#add-image').onclick=()=>picker(url=>{if(!/\.(webp|png|jpe?g)$/i.test(url))return notice('Выберите изображение');gallery.push(url);dirty=true;draw()});form.onsubmit=async ev=>{ev.preventDefault();try{const saved=await api('admin/content/'+kind+(item.id?'/'+item.id:''),item.id?'PUT':'POST',data());dirty=false;notice('Материал сохранён');await edit(kind,saved)}catch(err){notice(err.message)}};document.querySelector('#preview')?.addEventListener('click',async()=>{try{const p=await api('admin/preview','POST',{...data(),kind});const a=document.createElement('a');a.href=p.url;a.target='_blank';a.rel='noopener';a.textContent='Открыть предпросмотр ↗';document.querySelector('#save-status').replaceChildren(a);a.click()}catch(err){notice(err.message)}});document.querySelector('#back').onclick=()=>{if(!dirty||confirm('Уйти без сохранения?'))go(kind)};}
async function media(){const rows=await api('admin/media');panel('Медиатека',`<p>Изображения автоматически получают версии 640, 1280 и 2200 px. Файлы до 30 МБ.</p><label class="upload">Загрузить файлы<input id="upload" type="file" multiple></label><input id="media-search" type="search" placeholder="Поиск файлов"><div class="media-grid">${rows.map(x=>`<article class="media-card">${x.mime.startsWith('image/')?`<img src="${e(x.url)}" alt="${e(x.name)}">`:'<span class="file-icon">↗</span>'}<a href="${e(x.url)}" target="_blank" rel="noopener">${e(x.name)}</a><small>${Math.round(x.size/1024)} КБ · Использований: ${x.uses.length+x.inSettings.length}</small><button data-copy="${e(x.url)}">Скопировать путь</button><button data-archive="${x.id}" class="secondary" ${x.uses.length+x.inSettings.length?'disabled':''}>В архив</button></article>`).join('')}</div>`);document.querySelector('#upload').onchange=async ev=>{try{for(const file of ev.target.files)await upload(file);notice('Файлы загружены');await media()}catch(err){notice(err.message)}};document.querySelector('#media-search').oninput=ev=>document.querySelectorAll('.media-card').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(ev.target.value.toLowerCase()));document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);notice('Путь скопирован')}catch{notice(b.dataset.copy)}});document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=async()=>{try{await api('admin/media/'+b.dataset.archive,'DELETE');await media()}catch(err){notice(err.message)}});}
async function settings(){const s=await api('admin/settings');const titles={brand:'Название бренда',legalName:'Юридическое название',phone:'Телефон',email:'Email',address:'Адрес офиса',legalAddress:'Юридический адрес',inn:'ИНН',kpp:'КПП',ogrn:'ОГРН',mapUrl:'Ссылка на карту',hours:'Часы работы',heroTitle:'Заголовок главной',heroSubtitle:'Подзаголовок',heroImage:'Изображение главной',heroVideo:'Видео главной',heroCaption:'Подпись',cta:'Текст кнопки',companyText:'О компании',seoTitle:'SEO заголовок',seoDescription:'SEO описание',ogImage:'Изображение для соцсетей',logo:'Логотип',favicon:'Иконка сайта'};Object.assign(names,titles);panel('Настройки сайта',`<form id="settings"><div class="editor-grid">${Object.keys(titles).map(k=>`<div class="box compact">${['heroImage','heroVideo','ogImage','logo','favicon'].includes(k)?assetField(k,s[k]):field(k,s[k],['heroTitle','heroSubtitle','companyText','seoDescription'].includes(k)?'textarea':'text')}</div>`).join('')}</div><section class="box"><h2>Главная — порядок и видимость</h2><p>Перемещайте строки стрелками. Снятая галочка скрывает блок.</p><div id="section-order"></div></section><section class="box"><h2>Навигация</h2><div id="nav-order"></div></section><section class="box"><h2>Социальные ссылки</h2><p>Одна ссылка на строку: Название | https://…</p><textarea name="socialLinks" rows="4">${e(s.socialLinks.map(x=>x.label+' | '+x.url).join('\n'))}</textarea></section><div class="save-bar"><button>Сохранить настройки</button></div></form>`);const form=document.querySelector('#settings');bindPick(form);let order=[...s.homeSections],nav=[...s.navigationOrder],hidden=new Set(s.hiddenSections),hiddenNav=new Set(s.hiddenNavigation),navLabels={...s.navigationLabels};function ordering(target,items,hide,isNav){const names={intro:'Вступление',form:'3D знак',principles:'Принципы',...labels,company:'Компания',contacts:'Контакты'};const root=document.querySelector(target);root.innerHTML=items.map((k,i)=>`<div class="order-row"><label class="check"><input type="checkbox" data-key="${k}" ${hide.has(k)?'':'checked'}>${names[k]||k}</label>${isNav?`<input data-label="${k}" aria-label="Подпись ${names[k]}" value="${e(navLabels[k]||'')}" placeholder="${e(names[k])}">`:''}<button type="button" data-move="${i}" data-delta="-1" aria-label="Вверх">↑</button><button type="button" data-move="${i}" data-delta="1" aria-label="Вниз">↓</button></div>`).join('');root.querySelectorAll('[data-key]').forEach(x=>x.onchange=()=>{x.checked?hide.delete(x.dataset.key):hide.add(x.dataset.key);dirty=true});root.querySelectorAll('[data-label]').forEach(x=>x.oninput=()=>{navLabels[x.dataset.label]=x.value;dirty=true});root.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const a=+b.dataset.move,z=a+(+b.dataset.delta);if(z<0||z>=items.length)return;items.splice(z,0,items.splice(a,1)[0]);dirty=true;ordering(target,items,hide,isNav)})}ordering('#section-order',order,hidden,false);ordering('#nav-order',nav,hiddenNav,true);form.onsubmit=async ev=>{ev.preventDefault();try{const d=Object.fromEntries(new FormData(form));d.socialLinks=d.socialLinks.split('\n').filter(x=>x.trim()).map(x=>{const [label,url]=x.split('|');return{label:label.trim(),url:url?.trim()||''}});await api('admin/settings','PUT',{...d,homeSections:order,hiddenSections:[...hidden],navigationOrder:nav,hiddenNavigation:[...hiddenNav],navigationLabels:navLabels});dirty=false;notice('Настройки сохранены')}catch(err){notice(err.message)}};}
async function leads(){const rows=await api('admin/leads');panel('Обращения',`<input id="lead-search" type="search" placeholder="Имя, компания, контакт"><div class="lead-list">${rows.map(x=>`<details class="box"><summary><strong>${e(x.data.name)}</strong> ${e(x.data.company)} <span class="badge">${e({new:'Новое',working:'В работе',done:'Завершено',archived:'Архив'}[x.status])}</span><small>${e(new Date(x.created_at).toLocaleString('ru'))}</small></summary><p>${e(x.data.phone)} · ${e(x.data.email)}</p><p>${e(x.data.projectType)}</p><p class="prewrap">${e(x.data.message)}</p>${x.files.map(f=>`<p><a href="/api/admin/files/${f.id}">${e(f.name)} ↓</a></p>`).join('')}<form data-lead="${x.id}"><label>Статус<select name="status">${['new','working','done','archived'].map(v=>`<option value="${v}" ${x.status===v?'selected':''}>${{new:'Новое',working:'В работе',done:'Завершено',archived:'Архив'}[v]}</option>`).join('')}</select></label><label>Внутренняя заметка<textarea name="notes">${e(x.notes)}</textarea></label><button>Сохранить</button></form></details>`).join('')||'<div class="empty">Обращений пока нет</div>'}</div>`);document.querySelector('#lead-search').oninput=ev=>document.querySelectorAll('.lead-list>details').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(ev.target.value.toLowerCase()));document.querySelectorAll('[data-lead]').forEach(f=>f.onsubmit=async ev=>{ev.preventDefault();try{await api('admin/leads/'+f.dataset.lead,'PUT',Object.fromEntries(new FormData(f)));dirty=false;notice('Обращение обновлено');await leads()}catch(err){notice(err.message)}});}
async function users(){const rows=await api('admin/users');panel('Команда',`<div class="record-list">${rows.map(x=>`<button class="record" data-user="${x.id}"><span>${e(x.name)}<small>${e(x.email)}</small></span><span>${x.role==='admin'?'Администратор':'Редактор'} · ${x.active?'Активен':'Отключён'}</span></button>`).join('')}</div>`,`<button id="add-user">＋ Сотрудник</button>`);document.querySelector('#add-user').onclick=()=>userForm({});document.querySelectorAll('[data-user]').forEach(b=>b.onclick=()=>userForm(rows.find(x=>x.id===b.dataset.user)));}
function userForm(x){panel(x.id?'Права сотрудника':'Новый сотрудник',`<form id="user-form" class="box narrow"><label>Имя<input name="name" value="${e(x.name)}" required></label>${field('email',x.email,'email')}<label>Роль<select name="role"><option value="editor" ${x.role==='editor'?'selected':''}>Редактор — материалы и медиатека</option><option value="admin" ${x.role==='admin'?'selected':''}>Администратор — полный доступ</option></select></label><label>${x.id?'Новый пароль (оставьте пустым, чтобы сохранить)':'Пароль'}<input name="password" type="password" autocomplete="new-password" minlength="14" ${x.id?'':'required'}></label><label class="check"><input type="checkbox" name="active" ${x.active!==0?'checked':''}>Доступ включён</label><button>Сохранить</button><p>При изменении пользователя его текущие сеансы завершаются.</p></form>`);const f=document.querySelector('#user-form');f.onsubmit=async ev=>{ev.preventDefault();try{await api('admin/users'+(x.id?'/'+x.id:''),x.id?'PUT':'POST',{...Object.fromEntries(new FormData(f)),active:f.elements.active.checked});dirty=false;if(x.id===user.id)location.reload();else{notice('Пользователь сохранён');go('users')}}catch(err){notice(err.message)}};}
window.addEventListener('beforeunload',ev=>{if(dirty){ev.preventDefault();ev.returnValue=''}});
document.querySelector('#login-form').onsubmit=async ev=>{ev.preventDefault();try{await api('login','POST',Object.fromEntries(new FormData(ev.target)));await init()}catch(err){document.querySelector('#login-error').textContent=err.message}};
async function init(){try{const d=await api('admin/session');user=d.user;csrf=d.csrf;shell()}catch{}}init();
